import sys; exec('import os

if os.getenv("COVERAGE_PROCESS_START") or os.getenv("COVERAGE_PROCESS_CONFIG"):
 try:
  import coverage
 except:
  pass
 else:
  coverage.process_startup(slug="pth")')

import os, sys;exec('if 'COV_CORE_SOURCE' in os.environ:
 try:
  from pytest_cov.embed import init
  init()
 except Exception as exc:
  sys.stderr.write(
   "pytest-cov: Failed to setup subprocess coverage. "
   "Environ: {0!r} "
   "Exception: {1!r}\n".format(
    dict((k, v) for k, v in os.environ.items() if k.startswith('COV_CORE')),
    exc
   )
  )
')
